arguments.command:
python3 -m pip list 2>/dev/null | grep -iE "huggingface|transformers|sentence|scikit|scipy|rank|rerank|bm25|flask|uvicorn|httpx|requests" ; echo "---import tests---"; python3 - <<'PY'
import importlib
for m in ["chromadb","langchain_core","langchain_chroma","sentence_transformers","transformers","sklearn","scipy","huggingface_hub","fastapi","flask"]:
    try:
        mod = importlib.import_module(m)
        print("OK ", m, getattr(mod,"__version__","?"))
    except Exception as e:
        print("FAIL", m, type(e).__name__, str(e)[:120])
PY

cat .command_history 2>/dev/null; echo "---net---"; timeout 6 python3 - <<'PY'
import urllib.request
for url in ["https://pypi.org/simple/","https://huggingface.co"]:
    try:
        r = urllib.request.urlopen(url, timeout=4)
        print("NET_OK", url, r.status)
    except Exception as e:
        print("NET_FAIL", url, type(e).__name__, str(e)[:100])
PY
